"""
Moderation Model
================
Entity recording automated AI content moderation findings and review status.
"""

import uuid
from datetime import UTC, datetime

from sqlalchemy import Boolean, DateTime, Float, Index, String, Text, Uuid
from sqlalchemy.orm import Mapped, mapped_column

from app.db.base import Base, UUIDMixin


class ModerationFlag(Base, UUIDMixin):
    """Moderation record generated by AI analysis or user reports."""

    __tablename__ = "moderation_flags"

    content_type: Mapped[str] = mapped_column(
        String(20),
        nullable=False,
    )  # "post" | "comment"
    content_id: Mapped[uuid.UUID] = mapped_column(
        Uuid(as_uuid=True),
        nullable=False,
        index=True,
    )
    category: Mapped[str] = mapped_column(
        String(50),
        nullable=False,
    )  # "hate" | "harassment" | "sexual" | "violence" | "self-harm" | "spam" | "other"
    severity: Mapped[str] = mapped_column(
        String(20),
        nullable=False,
    )  # "low" | "medium" | "high" | "critical"
    score: Mapped[float] = mapped_column(
        Float,
        nullable=False,
    )  # 0.0 to 1.0 confidence/severity score
    action: Mapped[str] = mapped_column(
        String(20),
        nullable=False,
    )  # "allow" | "flag" | "block"
    reason: Mapped[str] = mapped_column(
        Text,
        nullable=False,
    )
    reviewed: Mapped[bool] = mapped_column(
        Boolean,
        default=False,
        nullable=False,
        index=True,
    )
    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True),
        default=lambda: datetime.now(UTC),
        nullable=False,
    )

    __table_args__ = (
        Index("ix_moderation_queue", "reviewed", "action"),
        Index("ix_moderation_content", "content_type", "content_id"),
    )

    def __repr__(self) -> str:
        return (
            f"<ModerationFlag id={self.id} type={self.content_type} "
            f"action={self.action} reviewed={self.reviewed}>"
        )
